xpath.script:
var canvas = document.getElementById('signature-pad');
var signaturePad = new SignaturePad(canvas);

function clearSignature() {
    signaturePad.clear();
}

document.getElementById('resume_form_id').addEventListener('submit', function (e) {
    if (!signaturePad.isEmpty()) {
        var base64Signature = signaturePad.toDataURL().split(',')[1];  // remove the "data:image/png;base64,"
        document.getElementById('signature-data').value = base64Signature;
    }
});
